-- CoWork China v27 - 03 数据 + 语义模型 + Skills 上传 / Load data, semantic models, skills
-- Run from the repo root:  snow sql -c <your_conn> -f deploy/v27/03_load_data.sql
USE WAREHOUSE COWORK_WH;
CREATE OR REPLACE TEMPORARY STAGE COWORK.APP.LOAD_TMP;
PUT file://deploy/v27/data/*.csv @COWORK.APP.LOAD_TMP AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
COPY INTO COWORK.APP.AGENTS FROM @COWORK.APP.LOAD_TMP/APP.AGENTS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.APP.SKILLS FROM @COWORK.APP.LOAD_TMP/APP.SKILLS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.KNOWLEDGE_BASE FROM @COWORK.APP.LOAD_TMP/DATA.KNOWLEDGE_BASE.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.LOGISTICS_SHIPMENTS FROM @COWORK.APP.LOAD_TMP/DATA.LOGISTICS_SHIPMENTS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.LOGISTICS_VEHICLES FROM @COWORK.APP.LOAD_TMP/DATA.LOGISTICS_VEHICLES.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.LOGISTICS_WAREHOUSES FROM @COWORK.APP.LOAD_TMP/DATA.LOGISTICS_WAREHOUSES.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.MFG_PRODUCTION_LINES FROM @COWORK.APP.LOAD_TMP/DATA.MFG_PRODUCTION_LINES.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.MFG_QUALITY_RECORDS FROM @COWORK.APP.LOAD_TMP/DATA.MFG_QUALITY_RECORDS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.MFG_WORK_ORDERS FROM @COWORK.APP.LOAD_TMP/DATA.MFG_WORK_ORDERS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.PROCUREMENT_MATERIALS FROM @COWORK.APP.LOAD_TMP/DATA.PROCUREMENT_MATERIALS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.PROCUREMENT_PO FROM @COWORK.APP.LOAD_TMP/DATA.PROCUREMENT_PO.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.PROCUREMENT_SUPPLIERS FROM @COWORK.APP.LOAD_TMP/DATA.PROCUREMENT_SUPPLIERS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.RETAIL_CUSTOMERS FROM @COWORK.APP.LOAD_TMP/DATA.RETAIL_CUSTOMERS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.RETAIL_ORDERS FROM @COWORK.APP.LOAD_TMP/DATA.RETAIL_ORDERS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
COPY INTO COWORK.DATA.RETAIL_PRODUCTS FROM @COWORK.APP.LOAD_TMP/DATA.RETAIL_PRODUCTS.csv FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE) FORCE=TRUE;
PUT file://deploy/v27/stage/semantic_models/*.yaml @COWORK.APP.SEMANTIC_MODELS AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
PUT file://deploy/v27/stage/skills/* @COWORK.APP.SKILLS AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
